import 'dart:convert';
import 'package:amina/core/data/meal_food_catalog.dart';
const int _batchSize=24;
const _style=<String,Object>{'brand':'IAMINA','version':'food-pictogram-v1','master_size':1024,'runtime_size':256,'aspect_ratio':'1:1','background':'transparent','camera':'three-quarter top-down, consistent 38 degree angle','lighting':'soft premium studio light, gentle teal bounce, warm natural highlights','material':'realistic food illustration with refined editorial finish, not cartoon, not emoji','composition':'single food concept centered, 72 percent frame occupancy, subtle contact shadow','accessibility':'must remain identifiable at 48 px without relying on text or color alone','forbidden':<String>['text','logo','watermark','hands','people','busy background','decorative props that obscure the food']};
const _launchPriorityIds=<String>['egg','whole_grain_bread','chicken','grilled_chicken','beef','sardines','salmon','milk','plain_yogurt','apple','banana','orange','tomato','potato','lentils','chickpeas','olive_oil','pizza','burger','moroccan_bread','msemen','baghrir','couscous_7_vegetables','harira','rfissa','chicken_preserved_lemon_tagine','kefta_tagine','zaalouk','taktouka','amlou','mint_tea','moroccan_sweet_tea','arabic_flatbread','tannour_bread','machboos_chicken','kabsa_chicken','mandi_chicken','harees','jareesh','thareed','balaleet','luqaimat','dates','ajwa_dates','arabic_coffee','karak_tea','shawarma_chicken','hummus'];
const _postV3AppendIds=<String>['matazeez','areeka','masoub','haneeth','maghsh','samak_mkashan','mahshoosh','marsah','gahwa_gishr','tasabea','mashgotha','miva_bread','qabooli','mishkak','omani_halwa','lamb_khuzi','bahraini_halwa','malgoum','louba_bahraini','bahraini_tikka','tashreeb','murabiyan','mutabbaq_zubaidi','dakkous','medfouna_rissani','tafernout_bread','berkoukes','tanjia_marrakchia','boulfaf','lben_moroccan','raib_moroccan','tagoula','ourkimen','tehal_stuffed_spleen'];
String _categoryDirection(MealFoodCategory c)=>switch(c){MealFoodCategory.breadGrain=>'show crumb, grain or layered texture clearly; warm bakery highlights',MealFoodCategory.moroccanDish=>'authentic Moroccan plating cues, restrained ceramic detail only when essential to recognition',MealFoodCategory.gulfDish=>'authentic Gulf presentation cues, rice and protein separation visible when relevant',MealFoodCategory.meatPoultry=>'clean cooked-food presentation, realistic browning',MealFoodCategory.fishSeafood=>'clean seafood presentation, silhouette readable at small size',MealFoodCategory.egg=>'simple preparation-specific form',MealFoodCategory.dairy=>'clean creamy texture and vessel only when needed for recognition',MealFoodCategory.legume=>'show whole legumes or recognizable cooked texture',MealFoodCategory.vegetable=>'fresh natural form',MealFoodCategory.fruit=>'fresh natural form',MealFoodCategory.nutSeed=>'macro-realistic natural texture',MealFoodCategory.fatSauce=>'ingredient identity remains primary',MealFoodCategory.drink=>'single culturally correct vessel',MealFoodCategory.sweetDessert=>'premium patisserie rendering, accurate local geometry',MealFoodCategory.snackFastFood=>'single recognizable serving',MealFoodCategory.saladMeal=>'top ingredients readable',MealFoodCategory.soup=>'single bowl, texture visible',MealFoodCategory.other=>'prioritize immediate recognition and natural food texture'};
List<MealFoodItem> _orderedItems(){final byId=<String,MealFoodItem>{for(final i in mealFoodCatalog)i.id:i};final missing=[..._launchPriorityIds,..._postV3AppendIds].where((id)=>!byId.containsKey(id)).toList();if(missing.isNotEmpty)throw StateError('Manifest references missing IDs: ${missing.join(', ')}');final p=_launchPriorityIds.toSet(),a=_postV3AppendIds.toSet();if(a.length!=_postV3AppendIds.length||p.intersection(a).isNotEmpty)throw StateError('Manifest IDs must be unique and disjoint.');final remaining=mealFoodCatalog.where((i)=>!p.contains(i.id)&&!a.contains(i.id)).toList()..sort((x,y){final c=x.category.index.compareTo(y.category.index);return c!=0?c:x.fr.compareTo(y.fr);});return <MealFoodItem>[..._launchPriorityIds.map((id)=>byId[id]!),...remaining,..._postV3AppendIds.map((id)=>byId[id]!)];}
Map<String,Object> _entry(MealFoodItem i,int n)=><String,Object>{'id':i.id,'asset':'assets/food/pictograms/v1/${i.pictogramKey}.webp','label_fr':i.fr,'label_en':i.en,'label_ar':i.ar,'category':i.category.name,'regions':i.regions.map((r)=>r.name).toList(growable:false),'priority':n<_launchPriorityIds.length?'launch':'catalog','batch':(n~/_batchSize)+1,'prompt':['Create one premium IAMINA food pictogram for ${i.en}.',_style['material']! as String,_style['camera']! as String,_style['lighting']! as String,_style['composition']! as String,_categoryDirection(i.category),'Transparent background. No text, no logo, no watermark.'].join(' ')};
int? _requestedBatch(List<String> args,int count){final xs=args.where((a)=>a.startsWith('--batch=')).toList();if(xs.length>1)throw ArgumentError('Use at most one --batch=N selector.');if(xs.isEmpty)return null;final n=int.tryParse(xs.single.substring(8));if(n==null||n<1||n>count)throw ArgumentError('Expected batch 1..$count');return n;}
void main(List<String> args){if(args.any((a)=>!a.startsWith('--batch=')))throw ArgumentError('Unsupported arguments');final ids=mealFoodCatalog.map((i)=>i.id).toSet();if(ids.length!=mealFoodCatalog.length)throw StateError('Duplicate food IDs');final ordered=_orderedItems();final count=(ordered.length/_batchSize).ceil();final requested=_requestedBatch(args,count);final indexed=<({int index,MealFoodItem item})>[for(var n=0;n<ordered.length;n++)(index:n,item:ordered[n])];final selected=requested==null?indexed:indexed.where((e)=>(e.index~/_batchSize)+1==requested).toList();print(const JsonEncoder.withIndent('  ').convert(<String,Object?>{'style':_style,'catalog_version':mealFoodCatalogVersion,'catalog_count':mealFoodCatalog.length,'selected_count':selected.length,'batch_size':_batchSize,'launch_count':_launchPriorityIds.length,'batch_count':count,'selected_batch':requested,'items':[for(final e in selected)_entry(e.item,e.index)]}));}
